def ts(ms): s=ms//1000; return f"{s//60}:{s%60:02d}"
blocos=[]; falantes=[]
for n,ad in ADS.items():
    d=json.load(open(f'VSL-Pipeline-AD0{n}/transcricao_raw.json'))
    U=d['utterances']; assert len(U)==len(ad['pt']),(n,len(U),len(ad['pt']))
    falas=[{"falante":ad['falantes'][u['speaker']],"ts":ts(u['start']),"en":u['text'],"pt":p} for u,p in zip(U,ad['pt'])]
    for f in falas:
        if f['falante'] not in falantes: falantes.append(f['falante'])
    prints=[{"ts":ts(s*1000),"legenda":leg,"arquivo":f"ad{n:02d}_{slug}_00-{s//60:02d}-{s%60:02d}.jpg","src":f"VSL-Pipeline-AD0{n}/cand/{s:05d}.jpg"} for s,slug,leg in ad['prints']]
    blocos.append({"n":n,"titulo":ad['titulo'],"inicio":"0:00","fim":ts(U[-1]['end']),"falas":falas,"prints":prints})
doc={"titulo":"ADS ESCALADO (3 anúncios) — Transcrição EN + Tradução PT-BR + Prints",
 "fonte":"Fonte: AD ESCALADO NOVO.mp4, AD ESCALADO NOVO 02.mp4 e AD ESCALADO NOVO 03.mp4 (404x718, ~2:04 cada). Transcrição: AssemblyAI (speaker labels). Tradução fiel: nomes, valores em dólares e referências mantidos como falados. Expert identificado pelas imagens como Joe Dispenza (o lettering do AD 02 nomeia 'JOE DISPENZA'); apresentador de TV no AD 01 identificado pela imagem.",
 "nota_prints":"Minutagens: cada fala traz o [m:ss] em que começa. Prints: um frame de cada cena/b-roll do anúncio, com legenda descrevendo a imagem e o texto da legenda queimada no vídeo, nomeados adNN_descricao_HH-MM-SS.jpg na pasta frames/.",
 "falantes":falantes,"blocos":blocos}
json.dump(doc,open('VSL-Pipeline-ADS/doc.json','w'),ensure_ascii=False,indent=1)
print(len(blocos),'ads',sum(len(b['prints']) for b in blocos),'prints')
